    ["Aucun objet dans cette liste pour l'instant."] = "Noch keine Gegenstände in dieser Liste.",
    ["Aucun objet mis aux dés pour l'instant. En groupe, chaque objet tiré au sort (Besoin, Cupidité, Passer) apparaît ici avec le dé de chaque joueur."] = "Noch kein Gegenstand zum Würfeln freigegeben. In der Gruppe erscheint hier jeder verloste Gegenstand (Bedarf, Gier, Passen) mit dem Wurf jedes Spielers.",
    ["Aucun sort dans cette liste pour l'instant."] = "Noch keine Zauber in dieser Liste.",
    ["Aucune compétence."] = "Keine Fertigkeit.",
    ["Aucune pièce d'équipement de qualité supérieure à celle-ci n'est vendue. Évite de monter jusqu'à Rare ou Épique si tu veux garder une marge de sécurité."] = "Es wird kein Ausrüstungsteil höherer Qualität als dieses verkauft. Geh nicht bis Selten oder Episch, wenn du einen Sicherheitsabstand behalten willst.",
    ["Aucune réputation pour l'instant."] = "Noch kein Ruf.",
