    ["Butin"] = "Beute",
    ["Butin instantané, flux à l'écran"] = "Sofortbeute, Feed auf dem Bildschirm",
    ["C'est parti"] = "Los geht's",
    ["C, U et les autres touches du jeu ouvrent le bon onglet ; la même touche ou Échap la referme."] = "C, U und die anderen Spieltasten öffnen den passenden Reiter; dieselbe Taste oder Esc schließt ihn wieder.",
    ["CONSEILLÉ"] = "EMPFOHLEN",
    ["CVars utiles (SoftTarget*, autoLoot*)"] = "Nützliche CVars (SoftTarget*, autoLoot*)",
    ["Cache la fenêtre de dialogue animée (« tête parlante ») qui apparaît en haut de l'écran."] = "Verbirgt das animierte Dialogfenster („sprechender Kopf“), das oben auf dem Bildschirm erscheint.",
    ["Cache les barres d'expérience et de réputation de Blizzard. L'XP reste lisible dans la barre d'infos de Platyplus (pourcentage, XP par heure, temps avant le niveau). Coupé, les barres reviennent tout de suite."] = "Verbirgt die Erfahrungs- und Rufleisten von Blizzard. Die EP bleiben in der Platyplus-Infoleiste lesbar (Prozent, EP pro Stunde, Zeit bis zur nächsten Stufe). Ausgeschaltet kommen die Leisten sofort zurück.",
    ["Cache les cartes pour cette quête ; la fenêtre de Blizzard reste ouverte."] = "Verbirgt die Karten für diese Quest; das Blizzard-Fenster bleibt offen.",
    ["Cache les messages d'erreur rouges qui s'affichent au milieu de l'écran."] = "Verbirgt die roten Fehlermeldungen in der Bildschirmmitte.",
    ["Cache les mobs que tu tiens déjà ; la fenêtre ne montre que ce qui demande ton attention."] = "Verbirgt die Gegner, die du schon hältst; das Fenster zeigt nur, was deine Aufmerksamkeit braucht.",
    ["Cacher les icônes de Questie"] = "Questie-Symbole ausblenden",
