    ["Niveau d'objet"] = "Gegenstandsstufe",
    ["Niveau d'objet moyen de ton équipement porté (clic : fiche du personnage)."] = "Durchschnittliche Gegenstandsstufe deiner getragenen Ausrüstung (Klick: Charakterfenster).",
    ["Noir par défaut."] = "Standardmäßig schwarz.",
    ["Nom ou numéro du sort, puis Entrée"] = "Zaubername oder -nummer, dann Eingabe",
    ["Nombre d'emplacements encore libres."] = "Anzahl der noch freien Plätze.",
    ["Nombre d'icônes"] = "Anzahl der Symbole",
    ["Nombre d'objets dont Platyplus connaît le prix à l'HDV sur ce royaume."] = "Anzahl der Gegenstände, deren Auktionshaus-Preis Platyplus auf diesem Realm kennt.",
    ["Nombre maximum d'icônes de sorts affichées sous la barre."] = "Maximale Anzahl der Zaubersymbole unter der Leiste.",
    ["Noms colorés selon la classe"] = "Namen nach Klasse gefärbt",
    ["Noms de canaux courts"] = "Kurze Kanalnamen",
    ["Normale (jeu)"] = "Normal (Spiel)",
    ["Nourriture choisie hors combat, puis la potion de soins prise en combat. Mis à jour quand tes sacs changent."] = "Außerhalb des Kampfes gewählte Nahrung, dann der im Kampf genutzte Heiltrank. Wird aktualisiert, wenn sich deine Taschen ändern.",
    ["Nouveaux messages"] = "Neue Nachrichten",
    ["Nécessite l'affichage sur un portrait."] = "Erfordert die Anzeige auf einem Porträt.",
    ["Nécessite l'alerte de proc."] = "Erfordert die Proc-Warnung.",
    ["Nécessite l'alerte des sacs presque pleins."] = "Erfordert die Warnung „Taschen fast voll“.",
    ["Nécessite l'alerte « healer à sec »."] = "Erfordert die Warnung „Heiler hat kein Mana“.",
    ["Nécessite la barre de coups blancs."] = "Erfordert die Leiste für normale Angriffe.",
